import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const q=JSON.parse('{"title":"QQ","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/qq.md","filePath":"zh/integrations/channels/qq.md","lastUpdated":1790952322000}'),n={name:"zh/integrations/channels/qq.md"};function l(s,t,i,h,d,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="qq" tabindex="-1">QQ <a class="header-anchor" href="#qq" aria-label="Permalink to &quot;QQ&quot;">​</a></h1><p>通过 QQ 开放平台的官方 Bot 接入 Memoh,支持私聊、群聊与话题(thread)会话。</p><div class="warning custom-block"><p class="custom-block-title">使用限制</p><ul><li>每个 QQ 账号最多创建 5 个 Bot。</li><li>回复按完整消息块送达,不做逐 token 流式输出。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一个 QQ 账号,用于登录 <a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot 开放平台</a>。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在-qq-开放平台创建-bot" tabindex="-1">1. 在 QQ 开放平台创建 Bot <a class="header-anchor" href="#_1-在-qq-开放平台创建-bot" aria-label="Permalink to &quot;1. 在 QQ 开放平台创建 Bot&quot;">​</a></h3><p>在 QQ Bot 开放平台:</p><ol><li>打开 <a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot 开放平台</a>,用 QQ 账号登录。</li><li>点 <strong>创建机器人</strong>(Create Bot),无需审批。</li><li>复制页面上显示的 <strong>AppID</strong> 和 <strong>AppSecret</strong>。<strong>AppSecret</strong> 只显示一次,务必存好。</li></ol><blockquote><p>官方资料:<a href="https://q.qq.com/" target="_blank" rel="noreferrer">QQ Bot 开放平台</a> · <a href="https://bot.q.qq.com/wiki/" target="_blank" rel="noreferrer">QQ Bot 文档</a></p></blockquote><h3 id="_2-在-memoh-里添加渠道" tabindex="-1">2. 在 Memoh 里添加渠道 <a class="header-anchor" href="#_2-在-memoh-里添加渠道" aria-label="Permalink to &quot;2. 在 Memoh 里添加渠道&quot;">​</a></h3><p>在 Memoh:</p><ol><li>打开 Bot 的 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>,选择 <strong>QQ</strong>。</li><li>粘贴 <strong>AppID</strong> 和 <strong>AppSecret</strong>。</li><li>按需调整可选设置:<strong>Markdown Support</strong> 与 <strong>Enable Input Hint</strong> 默认均已开启。</li><li>点 <strong>Save and Enable</strong>。</li></ol><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><strong>AppID</strong></td><td>是</td><td>Bot 的 App ID,创建 Bot 时在 QQ 开放平台页面上显示。</td></tr><tr><td><strong>AppSecret</strong></td><td>是</td><td>Bot 的 App Secret,只在创建时显示一次。</td></tr><tr><td><strong>Markdown Support</strong></td><td>否</td><td>启用 Markdown 格式(默认开启)。</td></tr><tr><td><strong>Enable Input Hint</strong></td><td>否</td><td>生成回复时显示「正在输入」提示(默认开启)。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>私聊给 Bot 发送 <code>/help</code>,或在群聊中 @Bot 并发送 <code>/help</code>。Bot 回复命令列表,说明渠道已接通。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>Bot 支持 QQ 群聊与话题(thread)会话:在群里 @Bot 即可触发回复。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>随时可在 Bot 的 <strong>平台</strong> 标签页停用或移除该渠道。更换凭据时,在同一面板更新 <strong>AppID</strong> / <strong>AppSecret</strong> 并保存即可。</p><h2 id="faq" tabindex="-1">常见问题 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;常见问题 {#faq}&quot;">​</a></h2><h3 id="appsecret-reset" tabindex="-1">AppSecret 找不到了 <a class="header-anchor" href="#appsecret-reset" aria-label="Permalink to &quot;AppSecret 找不到了 {#appsecret-reset}&quot;">​</a></h3><p><strong>AppSecret</strong> 只在创建 Bot 时显示一次。在 QQ 开放平台再次查看会强制重置;重置后,在 Memoh 里更新 <strong>AppSecret</strong> 并保存。</p>',24)])])}const g=e(n,[["render",l]]);export{q as __pageData,g as default};
